using System;
using System.Collections.Generic;
using System.Linq;

// Time O(depth) per check, space O(assignments).
class Program
{
    static void Main()
    {
        // Scopes are paths: tenant root / management group / subscription / resource group / resource
        var assignments = new List<(string principal, string role, string scope)>
        {
            ("alice", "Reader", "/mg/contoso"),
            ("bob", "Contributor", "/mg/contoso/sub/prod/rg/orders"),
            ("carol", "Owner", "/mg/contoso/sub/test")
        };
        string[] resources =
        {
            "/mg/contoso/sub/prod/rg/orders/fn-orders",
            "/mg/contoso/sub/prod/rg/billing/db-billing",
            "/mg/contoso/sub/test/rg/orders/fn-orders"
        };
        foreach (var r in resources)
            foreach (var who in new[] { "alice", "bob", "carol" })
                Console.WriteLine($"{who,-6} on {r}: {string.Join(",", RolesAt(assignments, who, r))}");
    }

    // A role applies if its scope is a prefix of the resource path (inheritance downward).
    static List<string> RolesAt(List<(string principal, string role, string scope)> a, string who, string resource)
    {
        return a.Where(x => x.principal == who &&
                (resource == x.scope || resource.StartsWith(x.scope + "/")))
            .Select(x => x.role).ToList();
    }
}

