// Time O(roles x actions), space O(roles).
class Role
{
    public string Name;
    public string[] Actions;      // control plane: manage the resource
    public string[] DataActions;  // data plane: read/write the data inside
}

class Program
{
    static bool Match(string pattern, string op) =>
        pattern == "*" || pattern == op ||
        (pattern.EndsWith("/*") && op.StartsWith(pattern.Substring(0, pattern.Length - 1)));

    static bool Allowed(IEnumerable<Role> roles, string op, bool data) =>
        roles.Any(r => (data ? r.DataActions : r.Actions).Any(p => Match(p, op)));

    static void Main()
    {
        var owner = new Role { Name = "Owner", Actions = new[] { "*" }, DataActions = new string[0] };
        var blobReader = new Role { Name = "Storage Blob Data Reader", Actions = new string[0],
            DataActions = new[] { "Storage/blobs/read" } };

        var ops = new[] { ("Storage/accounts/write", false), ("Storage/blobs/read", true) };
        foreach (var set in new[] { new[] { owner }, new[] { blobReader }, new[] { owner, blobReader } })
        {
            Console.WriteLine("Roles: " + string.Join(" + ", set.Select(r => r.Name)));
            foreach (var (op, data) in ops)
                Console.WriteLine($"  {(data ? "data   " : "control")} {op}: {Allowed(set, op, data)}");
        }
    }
}

using System;
using System.Collections.Generic;

// Models the isolated worker middleware idea with plain delegates.
// Time O(middlewares) per call, space O(middlewares).
delegate void Next(Context c);

class Context
{
    public Dictionary<string, string> Items = new Dictionary<string, string>();
    public string Input;
}

class Program
{
    static Next Build(List<Func<Context, Next, Action>> mws, Action<Context> handler)
    {
        Next end = c => handler(c);
        for (int i = mws.Count - 1; i >= 0; i--)
        {
            var mw = mws[i]; var next = end;       // each middleware wraps the next one
            end = c => mw(c, next)();
        }
        return end;
    }

    static void Main()
    {
        var mws = new List<Func<Context, Next, Action>>
        {
            (c, next) => () => {
                // 1) correlation id: reuse the incoming one, or create one
                c.Items["correlationId"] = c.Items.ContainsKey("x-correlation-id") ? c.Items["x-correlation-id"] : "gen-1234";
                Console.WriteLine("[mw1] before, id=" + c.Items["correlationId"]);
                next(c);
                Console.WriteLine("[mw1] after");
            },
            (c, next) => () => { Console.WriteLine("[mw2] logging scope: " + c.Items["correlationId"]); next(c); }
        };
        var pipeline = Build(mws, c => Console.WriteLine("[handler] processing '" + c.Input + "' with id " + c.Items["correlationId"]));
        var ctx = new Context { Input = "order-17" };
        ctx.Items["x-correlation-id"] = "abc-001";
        pipeline(ctx);
        pipeline(new Context { Input = "order-18" });
    }
}

