// Each "instance" has its own static-like cache, so scaled-out instances disagree.
// Time O(1) per lookup, space O(keys per instance).
class Instance
{
    public string Name;
    readonly Dictionary<string, string> cache = new Dictionary<string, string>();
    public string Get(string key, Dictionary<string, string> db)
    {
        if (cache.TryGetValue(key, out var v)) { Console.WriteLine($"  {Name}: cache hit {key}={v}"); return v; }
        v = db[key];
        cache[key] = v;
        Console.WriteLine($"  {Name}: loaded {key}={v} from db");
        return v;
    }
}

class Program
{
    static void Main()
    {
        var db = new Dictionary<string, string> { ["price"] = "10" };
        var a = new Instance { Name = "instance-A" };
        var b = new Instance { Name = "instance-B" };
        Console.WriteLine("Both instances read price:");
        a.Get("price", db); b.Get("price", db);
        db["price"] = "12";   // the database changes
        Console.WriteLine("After the database changed to 12:");
        a.Get("price", db);   // still serves the old value
        var c = new Instance { Name = "instance-C (new scale-out)" };
        c.Get("price", db);   // new instance sees the new value
        Console.WriteLine("Result: instances A/B say 10, instance C says 12.");
    }
}

using System;
using System.Collections.Generic;

// Retries + idempotency key + dead-letter after max attempts.
// Time O(messages x attempts), space O(processed ids).
class Msg { public string Id; public string Body; public int Delivery; }

class Program
{
    static HashSet<string> processed = new HashSet<string>();   // in real life: a table with a unique key
    static int charged = 0;
    static int failuresLeft = 2;

    static void Handle(Msg m)
    {
        if (m.Body == "poison") throw new Exception("cannot parse");
        if (processed.Contains(m.Id)) { Console.WriteLine($"  {m.Id}: duplicate, skipped"); return; }
        if (failuresLeft-- > 0) throw new Exception("transient failure");   // fails twice, then works
        charged++;                       // the side effect, done once
        processed.Add(m.Id);
        Console.WriteLine($"  {m.Id}: processed, total charged = {charged}");
    }

    static void Main()
    {
        var queue = new Queue<Msg>(new[] {
            new Msg { Id = "m1", Body = "pay 10" }, new Msg { Id = "m1", Body = "pay 10" },
            new Msg { Id = "m2", Body = "poison" } });
        var deadLetter = new List<Msg>();
        const int maxDelivery = 3;
        while (queue.Count > 0)
        {
            var m = queue.Dequeue(); m.Delivery++;
            Console.WriteLine($"{m.Id} delivery {m.Delivery}");
            try { Handle(m); }
            catch (Exception e)
            {
                Console.WriteLine("  error: " + e.Message);
                if (m.Delivery >= maxDelivery) { deadLetter.Add(m); Console.WriteLine("  -> dead-letter"); }
                else queue.Enqueue(m);
            }
        }
        Console.WriteLine("Dead-letter count: " + deadLetter.Count);
    }
}

