// Fake token as a plain object: validate issuer, audience, expiry, then scope or role.
// Time O(claims), space O(1).
class Token
{
    public string Issuer, Audience;
    public DateTime Expires;
    public string[] Scopes = new string[0];
    public string[] Roles = new string[0];
}

class Program
{
    const string ExpectedIssuer = "https://login.example/tenant-id/v2.0";
    const string ExpectedAudience = "api://orders-api";

    static string Authorize(Token t, DateTime now, string needScope, string needRole)
    {
        if (t.Issuer != ExpectedIssuer) return "401 wrong issuer";
        if (t.Audience != ExpectedAudience) return "401 wrong audience";
        if (t.Expires <= now) return "401 expired";
        // delegated (user) tokens carry scopes; app-only tokens carry roles
        if (needScope != null && t.Scopes.Contains(needScope)) return "200 ok (scope)";
        if (needRole != null && t.Roles.Contains(needRole)) return "200 ok (role)";
        return "403 forbidden";
    }

    static void Main()
    {
        var now = new DateTime(2026, 1, 1, 12, 0, 0, DateTimeKind.Utc);
        var good = new Token { Issuer = ExpectedIssuer, Audience = ExpectedAudience, Expires = now.AddMinutes(30), Scopes = new[] { "Orders.Read" } };
        var cases = new Dictionary<string, Token>
        {
            ["good token"] = good,
            ["wrong audience"] = new Token { Issuer = good.Issuer, Audience = "api://other", Expires = good.Expires },
            ["expired"] = new Token { Issuer = good.Issuer, Audience = good.Audience, Expires = now.AddMinutes(-1) },
            ["no needed scope"] = new Token { Issuer = good.Issuer, Audience = good.Audience, Expires = good.Expires, Scopes = new[] { "Other.Read" } }
        };
        foreach (var kv in cases)
            Console.WriteLine($"{kv.Key,-16} -> {Authorize(kv.Value, now, "Orders.Read", "Orders.Admin")}");
    }
}

using System;
using System.Collections.Generic;

// Durable-style replay: the orchestrator re-runs from the start, but finished
// activities return their saved result instead of running again.
// Time O(steps) per replay, space O(history).
class Program
{
    static List<string> history = new List<string>();   // saved results, like the event history
    static int activityRuns = 0;

    static string CallActivity(ref int step, string name, string input)
    {
        step++;
        if (step <= history.Count) { Console.WriteLine($"  replay: {name} -> {history[step - 1]} (from history)"); return history[step - 1]; }
        activityRuns++;
        string result = name + "(" + input + ")";
        history.Add(result);
        Console.WriteLine($"  run:    {name} -> {result}");
        return result;
    }

    static bool Orchestrator(bool crashAfterFirst)
    {
        int step = 0;
        string a = CallActivity(ref step, "Reserve", "order-7");
        if (crashAfterFirst) return false;                 // host restarts here
        string b = CallActivity(ref step, "Charge", a);
        CallActivity(ref step, "Ship", b);
        return true;
    }

    static void Main()
    {
        Console.WriteLine("Run 1 (crash after the first activity):");
        Orchestrator(true);
        Console.WriteLine("Run 2 (restart, replay from the beginning):");
        Orchestrator(false);
        Console.WriteLine("Activities that really executed: " + activityRuns + " (3, not 4)");
    }
}

