using System.Collections.Generic;

// Simulates peek-lock: if processing outlasts the lock, the message comes back.
// Time O(messages x deliveries), space O(messages).
class Message { public string Id; public int DeliveryCount; public int ProcessingSeconds; }

class Program
{
    const int LockSeconds = 30;
    const int MaxDeliveryCount = 3;

    static void Main()
    {
        var queue = new Queue<Message>();
        queue.Enqueue(new Message { Id = "fast", ProcessingSeconds = 5 });
        queue.Enqueue(new Message { Id = "slow", ProcessingSeconds = 45 });   // longer than the lock
        var deadLetter = new List<string>();

        while (queue.Count > 0)
        {
            var m = queue.Dequeue();
            m.DeliveryCount++;
            Console.Write($"{m.Id}: delivery {m.DeliveryCount}, work {m.ProcessingSeconds}s, lock {LockSeconds}s -> ");
            if (m.ProcessingSeconds <= LockSeconds)
            {
                Console.WriteLine("completed");
            }
            else if (m.DeliveryCount >= MaxDeliveryCount)
            {
                Console.WriteLine("lock lost, max deliveries reached, dead-lettered");
                deadLetter.Add(m.Id);
            }
            else
            {
                Console.WriteLine("lock lost, message becomes visible again");
                queue.Enqueue(m);   // another consumer may take it
            }
        }
        Console.WriteLine("Dead-letter queue: " + string.Join(",", deadLetter));
    }
}

