using System.Threading.Tasks;

// Cache-aside: check cache, on a miss load once, store with a time limit.
// Time O(1) per hit, one database call per key per expiry. Space O(keys).
class Program
{
    static Dictionary<string, (string value, DateTime expires)> cache = new Dictionary<string, (string, DateTime)>();
    static Dictionary<string, SemaphoreSlim> locks = new Dictionary<string, SemaphoreSlim>();
    static int dbCalls = 0;

    static async Task<string> GetAsync(string key)
    {
        if (TryGet(key, out var hit)) return hit;                 // 1) cache hit
        SemaphoreSlim gate;
        lock (locks) { if (!locks.TryGetValue(key, out gate)) locks[key] = gate = new SemaphoreSlim(1, 1); }
        await gate.WaitAsync();                                    // 2) only one caller loads the key
        try
        {
            if (TryGet(key, out hit)) return hit;                  // 3) someone else loaded it while we waited
            await Task.Delay(50);                                  // pretend slow database
            Interlocked.Increment(ref dbCalls);
            var value = "product-data-for-" + key;
            lock (cache) cache[key] = (value, DateTime.UtcNow.AddMinutes(5));   // 4) always set an expiry
            return value;
        }
        finally { gate.Release(); }
    }

    static bool TryGet(string key, out string value)
    {
        lock (cache)
        {
            if (cache.TryGetValue(key, out var e) && e.expires > DateTime.UtcNow) { value = e.value; return true; }
        }
        value = null; return false;
    }

    static async Task Main()
    {
        var tasks = new List<Task<string>>();
        for (int i = 0; i < 20; i++) tasks.Add(GetAsync("42"));   // 20 callers at once, same key
        await Task.WhenAll(tasks);
        Console.WriteLine("Callers: 20, database calls: " + dbCalls);
        await GetAsync("42");
        Console.WriteLine("After another read, database calls: " + dbCalls);
    }
}

