// Counts how requests spread over 4 physical partitions for two candidate keys.
// Time O(N), space O(partitions).
class Program
{
    static int Bucket(string key) => (int)((uint)key.GetHashCode() % 4);

    static int StableHash(string s) { int h = 17; foreach (char c in s) h = h * 31 + c; return h; }
    static int Part(string key) => (int)((uint)StableHash(key) % 4);

    static void Main()
    {
        var random = new Random(1);
        var requests = new List<(string tenant, string orderId)>();
        for (int i = 0; i < 1000; i++)
        {
            // 70% of traffic comes from one big tenant
            string tenant = random.Next(100) < 70 ? "big-tenant" : "tenant-" + random.Next(1, 30);
            requests.Add((tenant, "order-" + i));
        }
        Show("partition key = tenantId", requests.Select(r => r.tenant));
        Show("partition key = orderId  ", requests.Select(r => r.orderId));
    }

    static void Show(string label, IEnumerable<string> keys)
    {
        var counts = new int[4];
        foreach (var k in keys) counts[Part(k)]++;
        Console.WriteLine($"{label}: [{string.Join(", ", counts)}]  max share = {counts.Max() * 100 / 1000}%");
    }
}

