// Models the DefaultAzureCredential idea: ordered sources, first that works wins.
// Time O(sources), space O(1).
class Program
{
    delegate string Source();

    static string Try(string name, Dictionary<string, string> env, Source s)
    {
        try { var t = s(); Console.WriteLine($"  {name}: OK"); return t; }
        catch (Exception e) { Console.WriteLine($"  {name}: skipped ({e.Message})"); return null; }
    }

    static string Acquire(Dictionary<string, string> env)
    {
        var chain = new List<(string, Source)>
        {
            ("EnvironmentCredential", () => env.ContainsKey("CLIENT_SECRET") ? "token-from-env" : throw new Exception("no env vars")),
            ("ManagedIdentity", () => env.ContainsKey("IDENTITY_ENDPOINT") ? "token-from-managed-identity" : throw new Exception("not in Azure")),
            ("VisualStudio/AzureCli", () => env.ContainsKey("AZ_LOGIN") ? "token-from-az-login" : throw new Exception("not signed in"))
        };
        foreach (var (name, src) in chain)
        {
            var t = Try(name, env, src);
            if (t != null) return t;
        }
        throw new Exception("no credential available");
    }

    static void Main()
    {
        Console.WriteLine("On a laptop (az login done):");
        Console.WriteLine("  -> " + Acquire(new Dictionary<string, string> { ["AZ_LOGIN"] = "yes" }));
        Console.WriteLine("In Azure (managed identity):");
        Console.WriteLine("  -> " + Acquire(new Dictionary<string, string> { ["IDENTITY_ENDPOINT"] = "set" }));
    }
}

using System;
using System.Collections.Generic;

// APIM's rate-limit-by-key idea: the key is the customer, not the IP address.
// Time O(1) per request, space O(customers).
class Bucket { public double Tokens; public DateTime Last; }

class Program
{
    const double RatePerSecond = 2, Capacity = 4;
    static Dictionary<string, Bucket> buckets = new Dictionary<string, Bucket>();

    static bool Allow(string customerKey, DateTime now)
    {
        if (!buckets.TryGetValue(customerKey, out var b))
            buckets[customerKey] = b = new Bucket { Tokens = Capacity, Last = now };
        b.Tokens = Math.Min(Capacity, b.Tokens + (now - b.Last).TotalSeconds * RatePerSecond);   // refill
        b.Last = now;
        if (b.Tokens < 1) return false;     // would be HTTP 429
        b.Tokens -= 1;
        return true;
    }

    static void Main()
    {
        var t0 = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        // Same office IP (shared), two customers: A is noisy, B is calm.
        for (int i = 0; i < 7; i++)
            Console.WriteLine($"t=0.0s customer-A request {i + 1}: {(Allow("A", t0) ? "200" : "429")}");
        Console.WriteLine($"t=0.0s customer-B request 1: {(Allow("B", t0) ? "200" : "429")}");
        Console.WriteLine($"t=1.0s customer-A request 8: {(Allow("A", t0.AddSeconds(1)) ? "200" : "429")} (2 tokens refilled)");
    }
}

using System;

// Time O(1), space O(1).
class Program
{
    static void Main()
    {
        double slo = 99.9;                         // target: 99.9% of requests succeed
        long requestsPerMonth = 10_000_000;
        double budgetFraction = (100 - slo) / 100;
        long allowedFailures = (long)(requestsPerMonth * budgetFraction);
        Console.WriteLine($"SLO {slo}% of {requestsPerMonth:N0} requests -> error budget {allowedFailures:N0} failures");

        // Time-based view of the same number
        double minutesPerMonth = 30 * 24 * 60;
        Console.WriteLine($"Same as about {minutesPerMonth * budgetFraction:F1} minutes of full downtime per month");

        // Burn rate: how fast we use the budget
        long failuresSoFar = 6_000;
        double daysPassed = 10;
        double burn = (failuresSoFar / (double)allowedFailures) / (daysPassed / 30);
        Console.WriteLine($"After {daysPassed} days with {failuresSoFar:N0} failures, burn rate = {burn:F2}");
        Console.WriteLine(burn > 1 ? "Burn rate above 1: the budget will run out before month end -> alert / freeze releases"
                                   : "Within budget");
    }
}

