// W3C traceparent: 00-<trace id>-<span id>-<flags>. Producer writes it, consumer continues the trace.
// Time O(1), space O(1).
class QueueMessage
{
    public string Body;
    public Dictionary<string, string> Properties = new Dictionary<string, string>();
}

class Program
{
    static void Main()
    {
        var queue = new Queue<QueueMessage>();

        // Producer (service A)
        var traceId = ActivityTraceId.CreateRandom();
        var spanA = ActivitySpanId.CreateRandom();
        var msg = new QueueMessage { Body = "order-17" };
        msg.Properties["traceparent"] = $"00-{traceId}-{spanA}-01";
        queue.Enqueue(msg);
        Console.WriteLine("A sends " + msg.Body + " with traceparent " + msg.Properties["traceparent"]);

        // Consumer (service B), later, possibly another machine
        var received = queue.Dequeue();
        var parts = received.Properties["traceparent"].Split('-');
        var spanB = ActivitySpanId.CreateRandom();
        Console.WriteLine($"B handles {received.Body}: trace {parts[1]}, parent span {parts[2]}, own span {spanB}");
        Console.WriteLine("Same trace id in both services: " + (parts[1] == traceId.ToString()));
    }
}

using System;

// Time O(1), space O(1).
class Program
{
    // All parts must work: multiply availabilities.
    static double Serial(params double[] a) { double r = 1; foreach (var x in a) r *= x; return r; }
    // Any one part is enough: 1 - product of failures.
    static double Parallel(params double[] a) { double f = 1; foreach (var x in a) f *= 1 - x; return 1 - f; }

    static void Main()
    {
        double web = 0.999, db = 0.9995, queue = 0.999;
        double single = Serial(web, db, queue);
        Console.WriteLine($"One region, 3 parts in series: {single * 100:F3}% ({Downtime(single):F0} min/year down)");

        // Two regions: either region can serve (parallel), with a failover switch that is 99.99% reliable
        double region = single;
        double twoRegions = Parallel(region, region) * 0.9999;
        Console.WriteLine($"Two regions + failover switch:   {twoRegions * 100:F3}% ({Downtime(twoRegions):F0} min/year down)");

        // Adding a dependency with 99.9% lowers the total
        double withExtra = Serial(web, db, queue, 0.999);
        Console.WriteLine($"Add one more 99.9% dependency:   {withExtra * 100:F3}%");
    }

    static double Downtime(double a) => (1 - a) * 365 * 24 * 60;
}

