// No network: shows the request shape and a validator for the model's JSON answer.
// Real code would use AzureOpenAIClient with DefaultAzureCredential (no API key).
// Time O(size of JSON), space O(size of JSON).
class Program
{
    static void Main()
    {
        var request = new
        {
            model = "my-deployment-name",            // the deployment name, not the model family
            messages = new[]
            {
                new { role = "system", content = "Reply only with JSON: {\"sentiment\":\"positive|negative\",\"score\":0-1}" },
                new { role = "user", content = "The delivery was late but support was great." }
            },
            response_format = new { type = "json_object" },
            temperature = 0
        };
        Console.WriteLine("Request: " + JsonSerializer.Serialize(request));

        string[] replies = { "{\"sentiment\":\"positive\",\"score\":0.7}", "Sure! Here is the JSON: {oops", "{\"sentiment\":\"happy\",\"score\":3}" };
        foreach (var reply in replies)
            Console.WriteLine(Validate(reply));
    }

    static string Validate(string json)
    {
        try
        {
            using (var doc = JsonDocument.Parse(json))
            {
                var root = doc.RootElement;
                string s = root.GetProperty("sentiment").GetString();
                double score = root.GetProperty("score").GetDouble();
                if (s != "positive" && s != "negative") return "REJECT bad sentiment value: " + s;
                if (score < 0 || score > 1) return "REJECT score out of range: " + score;
                return "OK " + s + " " + score;
            }
        }
        catch (Exception e) when (e is JsonException || e is KeyNotFoundException || e is InvalidOperationException)
        {
            return "REJECT not valid JSON: " + json;
        }
    }
}

