// IaC idea: the code is the desired state; compare it to what really exists.
// Time O(resources x properties), space O(resources).
class Program
{
    static void Main()
    {
        var desired = new Dictionary<string, Dictionary<string, string>>
        {
            ["storage-orders"] = new Dictionary<string, string> { ["sku"] = "Standard_ZRS", ["publicAccess"] = "false" },
            ["func-orders"] = new Dictionary<string, string> { ["plan"] = "FlexConsumption", ["maxInstances"] = "20" }
        };
        var actual = new Dictionary<string, Dictionary<string, string>>
        {
            ["storage-orders"] = new Dictionary<string, string> { ["sku"] = "Standard_ZRS", ["publicAccess"] = "true" },  // changed by hand
            ["func-orders"] = new Dictionary<string, string> { ["plan"] = "FlexConsumption", ["maxInstances"] = "20" },
            ["vm-temp"] = new Dictionary<string, string> { ["size"] = "D4s" }                                            // created by hand
        };

        foreach (var name in desired.Keys.Union(actual.Keys).OrderBy(x => x))
        {
            if (!actual.ContainsKey(name)) { Console.WriteLine($"MISSING   {name} (in code, not in Azure)"); continue; }
            if (!desired.ContainsKey(name)) { Console.WriteLine($"UNMANAGED {name} (in Azure, not in code)"); continue; }
            foreach (var prop in desired[name].Keys)
                if (desired[name][prop] != actual[name][prop])
                    Console.WriteLine($"DRIFT     {name}.{prop}: code={desired[name][prop]} azure={actual[name][prop]}");
        }
    }
}

