// The identity provider (Entra ID) trusts a CI token only if issuer, subject and audience match.
// Placeholders only, no real ids. Time O(credentials), space O(1).
class Federated { public string Issuer, Subject, Audience; }
class CiToken { public string Issuer, Subject, Audience; }

class Program
{
    static bool Exchange(List<Federated> configured, CiToken t) =>
        configured.Any(f => f.Issuer == t.Issuer && f.Subject == t.Subject && f.Audience == t.Audience);

    static void Main()
    {
        const string issuer = "https://token.ci.example";
        var prod = new Federated { Issuer = issuer, Subject = "repo:contoso/shop:environment:production", Audience = "api://AzureADTokenExchange" };
        var test = new Federated { Issuer = issuer, Subject = "repo:contoso/shop:environment:test", Audience = "api://AzureADTokenExchange" };

        var cases = new (string label, List<Federated> identity, CiToken token)[]
        {
            ("prod job -> prod identity", new List<Federated> { prod }, new CiToken { Issuer = issuer, Subject = prod.Subject, Audience = prod.Audience }),
            ("test job -> prod identity", new List<Federated> { prod }, new CiToken { Issuer = issuer, Subject = test.Subject, Audience = test.Audience }),
            ("fork PR  -> prod identity", new List<Federated> { prod }, new CiToken { Issuer = issuer, Subject = "repo:attacker/shop:pull_request", Audience = prod.Audience }),
            ("test job -> test identity", new List<Federated> { test }, new CiToken { Issuer = issuer, Subject = test.Subject, Audience = test.Audience })
        };
        foreach (var c in cases)
            Console.WriteLine($"{c.label}: {(Exchange(c.identity, c.token) ? "token issued" : "DENIED")}");
    }
}

using System;
using System.Linq;

// Same user always gets the same version, and the percentage can be raised step by step.
// Time O(users), space O(1).
class Program
{
    static int Bucket(string userId)
    {
        int h = 17;
        foreach (char c in userId) h = unchecked(h * 31 + c);
        return (int)((uint)h % 100);          // 0..99
    }

    static string Version(string userId, int canaryPercent) =>
        Bucket(userId) < canaryPercent ? "v2 (canary)" : "v1 (stable)";

    static void Main()
    {
        var users = Enumerable.Range(1, 1000).Select(i => "user-" + i).ToArray();
        foreach (int percent in new[] { 0, 5, 25, 100 })
        {
            int onCanary = users.Count(u => Version(u, percent).StartsWith("v2"));
            Console.WriteLine($"canary {percent,3}% -> {onCanary,4} of {users.Length} users on v2");
        }
        Console.WriteLine("Same user, repeated: " + Version("user-7", 25) + ", " + Version("user-7", 25));
        Console.WriteLine("Rollback = set percent to 0: " + Version("user-7", 0));
    }
}

using System;

// Break-even between pay-per-use and a fixed monthly plan. Prices are made-up placeholders.
// Time O(1), space O(1).
class Program
{
    static void Main()
    {
        double pricePerMillionExecutions = 0.20;
        double pricePerGbSecond = 0.000016;
        double memoryGb = 0.5, secondsPerExecution = 0.4;
        double fixedPlanPerMonth = 70.0;

        Console.WriteLine("executions/month | serverless | fixed plan | cheaper");
        foreach (long executions in new long[] { 100_000, 1_000_000, 10_000_000, 50_000_000, 200_000_000 })
        {
            double serverless = executions / 1_000_000.0 * pricePerMillionExecutions
                              + executions * secondsPerExecution * memoryGb * pricePerGbSecond;
            Console.WriteLine($"{executions,16:N0} | {serverless,10:F2} | {fixedPlanPerMonth,10:F2} | {(serverless < fixedPlanPerMonth ? "serverless" : "fixed")}");
        }
        // Break-even: cost per execution
        double perExecution = pricePerMillionExecutions / 1_000_000.0 + secondsPerExecution * memoryGb * pricePerGbSecond;
        Console.WriteLine($"Break-even about {fixedPlanPerMonth / perExecution:N0} executions per month");
    }
}

using System;
using System.Linq;

// Time O(n log n) for the sort, space O(n).
class Program
{
    static double Percentile(double[] sorted, double p)
    {
        int rank = (int)Math.Ceiling(p / 100.0 * sorted.Length) - 1;   // nearest-rank method
        return sorted[Math.Max(0, rank)];
    }

    static void Main()
    {
        // 100 request times in ms: before and after the deployment
        var before = Enumerable.Repeat(120.0, 100).ToArray();
        var after = Enumerable.Repeat(120.0, 92).Concat(Enumerable.Repeat(3000.0, 8)).ToArray();   // 8% very slow

        Report("before deploy", before);
        Report("after deploy ", after);
    }

    static void Report(string label, double[] times)
    {
        var sorted = times.OrderBy(x => x).ToArray();
        Console.WriteLine($"{label}: avg {times.Average():F0} ms, p50 {Percentile(sorted, 50):F0} ms, p95 {Percentile(sorted, 95):F0} ms, p99 {Percentile(sorted, 99):F0} ms");
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

// A repository that cannot be used without a tenant id (like an EF Core global query filter).
// Time O(rows), space O(1) extra.
class Order { public int Id; public string TenantId; public string Item; }

class TenantRepo
{
    readonly List<Order> all;
    readonly string tenantId;                       // comes from the validated token, never from the request body
    public TenantRepo(List<Order> all, string tenantId) { this.all = all; this.tenantId = tenantId; }

    public IEnumerable<Order> Query() => all.Where(o => o.TenantId == tenantId);   // the filter is built in
    public Order Get(int id) => Query().FirstOrDefault(o => o.Id == id);
}

class Program
{
    static void Main()
    {
        var data = new List<Order>
        {
            new Order { Id = 1, TenantId = "t-acme", Item = "Laptop" },
            new Order { Id = 2, TenantId = "t-acme", Item = "Phone" },
            new Order { Id = 3, TenantId = "t-globex", Item = "Secret roadmap" }
        };
        var acme = new TenantRepo(data, "t-acme");
        Console.WriteLine("Acme sees: " + string.Join(", ", acme.Query().Select(o => o.Item)));
        var guess = acme.Get(3);   // Acme guesses another tenant's order id
        Console.WriteLine("Acme asks for order 3: " + (guess == null ? "not found (isolated)" : guess.Item));
    }
}
